await client.query(`CREATE TABLE IF NOT EXISTS fidelidade_saldos(barbearia_id INTEGER NOT NULL REFERENCES barbearias(id) ON DELETE CASCADE,cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,pontos INTEGER DEFAULT 0,atualizado_em TIMESTAMP DEFAULT NOW(),PRIMARY KEY(barbearia_id,cliente_id))`);
await client.query(`CREATE TABLE IF NOT EXISTS pacotes(id SERIAL PRIMARY KEY,barbearia_id INTEGER NOT NULL REFERENCES barbearias(id) ON DELETE CASCADE,nome VARCHAR(160) NOT NULL,preco NUMERIC(10,2) DEFAULT 0,descricao TEXT,ativo BOOLEAN DEFAULT true,criado_em TIMESTAMP DEFAULT NOW())`);
await client.query(`CREATE TABLE IF NOT EXISTS oauth_states(id SERIAL PRIMARY KEY,barbearia_id INTEGER NOT NULL REFERENCES barbearias(id) ON DELETE CASCADE,state TEXT UNIQUE NOT NULL,code_verifier TEXT NOT NULL,expira_em TIMESTAMP NOT NULL,criado_em TIMESTAMP DEFAULT NOW())`);
const extras=[['clientes','barbearia_id','INTEGER'],['clientes','email','VARCHAR(160)'],['clientes','observacoes','TEXT'],['clientes','data_nascimento','DATE'],['clientes','preferencias','TEXT'],['clientes','criado_em','TIMESTAMP DEFAULT NOW()'],['barbeiros','barbearia_id','INTEGER'],['barbeiros','telefone','VARCHAR(30)'],['barbeiros','ativo','BOOLEAN DEFAULT true'],['barbeiros','comissao_servico_pct','NUMERIC(5,2) DEFAULT 0'],['barbeiros','comissao_produto_pct','NUMERIC(5,2) DEFAULT 0'],['servicos','barbearia_id','INTEGER'],['servicos','preco','NUMERIC(10,2) DEFAULT 0'],['servicos','ativo','BOOLEAN DEFAULT true'],['horarios_trabalho','barbearia_id','INTEGER'],['agendamentos','barbearia_id','INTEGER'],['agendamentos','status',"VARCHAR(30) DEFAULT 'agendado'"],['agendamentos','observacoes','TEXT'],['agendamentos','origem',"VARCHAR(30) DEFAULT 'painel'"],['agendamentos','criado_em','TIMESTAMP DEFAULT NOW()'],['agendamentos','token_publico','TEXT'],['agendamentos','cancelamento_limite_horas','INTEGER DEFAULT 6'],['usuarios','barbeiro_id','INTEGER'],['assinaturas','checkout_url','TEXT'],['assinaturas','provedor_status','VARCHAR(40)'],['assinaturas','atualizado_em','TIMESTAMP DEFAULT NOW()'],['barbearias','pagamento_agendamento',"VARCHAR(20) DEFAULT 'nenhum'"],['barbearias','percentual_sinal','NUMERIC(5,2) DEFAULT 50'],['barbearias','banner_url','TEXT'],['barbearias','cor_secundaria',"VARCHAR(20) DEFAULT '#111827'"],['barbearias','cor_botao',"VARCHAR(20) DEFAULT '#f59e0b'"],['barbearias','cor_fundo',"VARCHAR(20) DEFAULT '#f7f7f8'"],['barbearias','tema',"VARCHAR(20) DEFAULT 'claro'"],['barbearias','descricao_publica','TEXT'],['barbearias','texto_boas_vindas','VARCHAR(200)'],['barbearias','instagram','VARCHAR(160)'],['barbearias','whatsapp_publico','VARCHAR(30)'],['barbearias','mostrar_precos','BOOLEAN DEFAULT true'],['barbearias','mostrar_duracao','BOOLEAN DEFAULT true'],['barbearias','politica_cancelamento','TEXT'],['barbearias','aceitar_mercadopago','BOOLEAN DEFAULT false'],['barbearias','mp_aceitar_pix','BOOLEAN DEFAULT true'],['barbearias','mp_aceitar_cartao','BOOLEAN DEFAULT true'],['barbearias','aceitar_pix_manual','BOOLEAN DEFAULT false'],['barbearias','pix_chave','TEXT'],['barbearias','pix_nome','VARCHAR(160)'],['barbearias','pix_banco','VARCHAR(120)'],['barbearias','aceitar_dinheiro','BOOLEAN DEFAULT true'],['agendamentos','forma_pagamento',"VARCHAR(30) DEFAULT 'nao_informado'"],['agendamentos','status_pagamento',"VARCHAR(30) DEFAULT 'nao_exigido'"],['agendamentos','valor_cobrado','NUMERIC(10,2) DEFAULT 0'],['agendamentos','valor_pago','NUMERIC(10,2) DEFAULT 0'],['reservas_pagamento','forma_pagamento',"VARCHAR(30) DEFAULT 'mercado_pago'"],['automacoes_config','canal_lembretes',"VARCHAR(30) DEFAULT 'cloud_api'"],['automacoes_config','mensagem_lembrete_24h','TEXT'],['automacoes_config','mensagem_lembrete_2h','TEXT'],['automacoes_config','mensagem_pos_atendimento','TEXT'],['usuarios','telefone','VARCHAR(30)'],['usuarios','atualizado_em','TIMESTAMP DEFAULT NOW()'],['barbearias','excluido_em','TIMESTAMP'],['barbearias','is_system','BOOLEAN NOT NULL DEFAULT false'],['barbearias','email_verificado','BOOLEAN NOT NULL DEFAULT true']];for(const[t,c,ty]of extras)await client.query(`ALTER TABLE ${t} ADD COLUMN IF NOT EXISTS ${c} ${ty}`);
const hasBootstrap=!!(process.env.BOOTSTRAP_ADMIN_EMAIL&&process.env.BOOTSTRAP_ADMIN_PASSWORD);
