if(!t.rowCount){const legacy=await client.query(`SELECT ((SELECT COUNT(*) FROM clientes)+(SELECT COUNT(*) FROM barbeiros)+(SELECT COUNT(*) FROM servicos)+(SELECT COUNT(*) FROM horarios_trabalho)+(SELECT COUNT(*) FROM agendamentos))::bigint n`);if(hasBootstrap||Number(legacy.rows[0].n)>0)t=await client.query(`INSERT INTO barbearias(nome,slug,ativo,is_system,email_verificado) VALUES($1,$2,true,false,true) RETURNING *`,[cleanEnv(process.env.BOOTSTRAP_BARBERSHOP_NAME||'Barbearia Inicial',120),'barbearia-inicial']);}
