if(tid)for(const table of ['clientes','barbeiros','servicos','horarios_trabalho','agendamentos'])await client.query(`UPDATE ${table} SET barbearia_id=$1 WHERE barbearia_id IS NULL`,[tid]);
else{for(const table of ['clientes','barbeiros','servicos','horarios_trabalho','agendamentos']){const n=await client.query(`SELECT COUNT(*)::int n FROM ${table} WHERE barbearia_id IS NULL`);if(Number(n.rows[0].n)>0)throw new Error(`Há dados legados em ${table} sem tenant e nenhuma barbearia operacional foi criada.`)}}
const reservedSystem=await client.query(`SELECT id,is_system FROM barbearias WHERE slug='barberflow-system' LIMIT 1`);if(reservedSystem.rowCount&&!reservedSystem.rows[0].is_system)throw new Error('O slug reservado barberflow-system já está em uso por uma barbearia real. Renomeie-a antes da migração.');
let sys=await client.query(`SELECT id FROM barbearias WHERE is_system=true ORDER BY id LIMIT 1`);if(!sys.rowCount)sys=await client.query(`INSERT INTO barbearias(nome,slug,ativo,is_system,email_verificado) VALUES('BarberFlow System','barberflow-system',false,true,true) RETURNING id`);const systemTenantId=sys.rows[0].id;
await client.query(`UPDATE barbearias SET ativo=false,email_verificado=true WHERE id=$1`,[systemTenantId]);
await client.query(`DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_usuarios_barbeiro') THEN ALTER TABLE usuarios ADD CONSTRAINT fk_usuarios_barbeiro FOREIGN KEY (barbeiro_id) REFERENCES barbeiros(id) ON DELETE SET NULL; END IF; END $$`);await client.query(`CREATE UNIQUE INDEX IF NOT EXISTS ux_usuarios_barbeiro ON usuarios(barbearia_id,barbeiro_id) WHERE barbeiro_id IS NOT NULL`);await client.query(`CREATE UNIQUE INDEX IF NOT EXISTS ux_horario_tenant_dia ON horarios_trabalho(barbearia_id,barbeiro_id,dia_semana)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_agenda_tenant_data ON agendamentos(barbearia_id,data,barbeiro_id)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_reservas_slot ON reservas_pagamento(barbearia_id,data,barbeiro_id,horario)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_reservas_status_expira ON reservas_pagamento(status,expira_em)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_clientes_tenant_nome ON clientes(barbearia_id,nome)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_oauth_states_expira ON oauth_states(expira_em)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_integracoes_pagamento_tenant ON integracoes_pagamento(barbearia_id,provedor,status)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_whatsapp_phone ON integracoes_whatsapp(phone_number_id,status)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_automacoes_envios ON automacoes_envios(barbearia_id,tipo,enviado_em)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_whatsapp_qr_status ON integracoes_whatsapp_qr(status,atualizado_em)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_agendamentos_tenant_status_data ON agendamentos(barbearia_id,status,data)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_vendas_tenant_criado ON vendas(barbearia_id,criado_em DESC)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_produtos_tenant_ativo ON produtos(barbearia_id,ativo,nome)`);const skuDup=await client.query(`SELECT barbearia_id,lower(btrim(sku)) sku_norm,COUNT(*)::int n FROM produtos WHERE NULLIF(btrim(COALESCE(sku,'')),'') IS NOT NULL GROUP BY barbearia_id,lower(btrim(sku)) HAVING COUNT(*)>1 LIMIT 5`);if(skuDup.rowCount)throw new Error(`Existem SKUs duplicados no mesmo tenant. Corrija antes da migração: ${JSON.stringify(skuDup.rows)}`);await client.query(`CREATE UNIQUE INDEX IF NOT EXISTS ux_produtos_tenant_sku_lower ON produtos(barbearia_id,lower(btrim(sku))) WHERE NULLIF(btrim(COALESCE(sku,'')),'') IS NOT NULL`);await client.query(`CREATE INDEX IF NOT EXISTS ix_fila_tenant_status ON fila_espera(barbearia_id,status,criado_em)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_clientes_tenant_telefone ON clientes(barbearia_id,telefone)`);await client.query(`CREATE INDEX IF NOT EXISTS ix_password_resets_token ON password_resets(token_hash,expira_em)`);await client.query(`CREATE UNIQUE INDEX IF NOT EXISTS ux_assinaturas_cobrancas_ref ON assinaturas_cobrancas(provedor,referencia_externa) WHERE referencia_externa IS NOT NULL`);await client.query(`CREATE INDEX IF NOT EXISTS ix_assinaturas_cobrancas_periodo ON assinaturas_cobrancas(competencia,status)`);
if(tid&&!(await client.query(`SELECT 1 FROM assinaturas WHERE barbearia_id=$1`,[tid])).rowCount)await client.query(`INSERT INTO assinaturas(barbearia_id,plano,status,inicio,fim_trial) VALUES($1,'premium','trial',CURRENT_DATE,CURRENT_DATE+INTERVAL '7 days')`,[tid]);
await client.query(`UPDATE assinaturas SET plano='premium', atualizado_em=NOW() WHERE status='trial'`);
