await client.query(`UPDATE assinaturas SET status='trial',inicio=COALESCE(inicio,CURRENT_DATE),fim_trial=CASE WHEN status='trial_pendente' OR fim_trial IS NULL THEN CURRENT_DATE+INTERVAL '7 days' ELSE fim_trial END,atualizado_em=NOW() WHERE status='trial_pendente' OR (status='trial' AND fim_trial IS NULL)`);
const email=cleanEnv(process.env.BOOTSTRAP_ADMIN_EMAIL,160).toLowerCase(),senhaBootstrap=String(process.env.BOOTSTRAP_ADMIN_PASSWORD||'');if(email&&senhaBootstrap){if(!tid)throw new Error('BOOTSTRAP_ADMIN_* informado, mas nenhuma barbearia operacional foi criada');if(senhaBootstrap.length<12)throw new Error('BOOTSTRAP_ADMIN_PASSWORD deve ter pelo menos 12 caracteres');if(!(await client.query(`SELECT 1 FROM usuarios WHERE LOWER(email)=LOWER($1)`,[email])).rowCount){const hash=await bcrypt.hash(senhaBootstrap,12);await client.query(`INSERT INTO usuarios(barbearia_id,nome,email,senha_hash,papel,ativo) VALUES($1,'Administrador',$2,$3,'dono',true)`,[tid,email,hash]);console.log(`Usuário inicial configurado: ${email}`);}}else if(process.env.NODE_ENV==='production'){console.log('BOOTSTRAP_ADMIN_* ausentes: nenhum usuário dono padrão foi criado (comportamento seguro).');}
